$(
=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=
  Subcomplex modules
=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=
$)

  $c CMod $. $( Token for the class of subcomplex modules. $)

  $( Syntax for the class of subcomplex modules. $)
  cclm $a class CMod $.

  ${
    $d f k w F $.  $d f k w K $.  $d f k w W $.
    $( Define the class of subcomplex modules, which are left modules over a
       subring of the field of complex numbers ` CCfld ` , which allows to use
       the complex addition, multiplication, etc. in theorems about subcomplex
       modules.  Since the field of complex numbers is commutative and so are
       its subrings (see ~ subrgcrng ), left modules over such subrings are the
       same as right modules, see ~ rmodislmod .  Therefore, we drop the word
       "left" from "subcomplex left module".  (Contributed by Mario Carneiro,
       16-Oct-2015.) $)
    df-clm $a |- CMod = { w e. LMod | [. ( Scalar ` w ) / f ].
      [. ( Base ` f ) / k ].
        ( f = ( CCfld |`s k ) /\ k e. ( SubRing ` CCfld ) ) } $.

    isclm.f $e |- F = ( Scalar ` W ) $.
    isclm.k $e |- K = ( Base ` F ) $.
    $( A subcomplex module is a left module over a subring of the field of
       complex numbers.  (Contributed by Mario Carneiro, 16-Oct-2015.) $)
    isclm $p |- ( W e. CMod <-> ( W e. LMod /\
      F = ( CCfld |`s K ) /\ K e. ( SubRing ` CCfld ) ) ) $=
      ( vf vk vw cclm wcel clmod ccnfld cress co wceq cfv wa cv cbs csca csubrg
      w3a wsbc cvv fvexd id fveq2 eqtr4di sylan9eqr adantr fveq2d oveq2d eleq1d
      eqeq12d anbi12d sbcied df-clm elrab2 3anass bitr4i ) CIJCKJZALBMNZOZBLUAP
      ZJZQZQVAVCVEUBFRZLGRZMNZOZVHVDJZQZGVGSPZUCZFHRZTPZUCVFHCKIVOCOZVNVFFVPUDV
      QVOTUEVQVGVPOZQZVLVFGVMUDVSVGSUEVSVHVMOZQZVJVCVKVEWAVGAVIVBVSVGAOVTVRVQVG
      VPAVRUFVQVPCTPAVOCTUGDUHUIZUJWAVHBLMVTVSVHVMBVTUFVSVMASPBVSVGASWBUKEUHUIZ
      ULUNWAVHBVDWCUMUOUPUPHFGUQURVAVCVEUSUT $.

    $( The ring of scalars ` F ` of a subcomplex module is the restriction of
       the field of complex numbers to the base set of ` F ` .  (Contributed by
       Mario Carneiro, 16-Oct-2015.) $)
    clmsca $p |- ( W e. CMod -> F = ( CCfld |`s K ) ) $=
      ( cclm wcel clmod ccnfld cress co wceq csubrg cfv isclm simp2bi ) CFGCHGA
      IBJKLBIMNGABCDEOP $.

    $( The base set of the ring of scalars of a subcomplex module is the base
       set of a subring of the field of complex numbers.  (Contributed by Mario
       Carneiro, 16-Oct-2015.) $)
    clmsubrg $p |- ( W e. CMod -> K e. ( SubRing ` CCfld ) ) $=
      ( cclm wcel clmod ccnfld cress co wceq csubrg cfv isclm simp3bi ) CFGCHGA
      IBJKLBIMNGABCDEOP $.
  $}

  $( A subcomplex module is a left module.  (Contributed by Mario Carneiro,
     16-Oct-2015.) $)
  clmlmod $p |- ( W e. CMod -> W e. LMod ) $=
    ( cclm wcel clmod csca cfv ccnfld cbs cress wceq csubrg eqid isclm simp1bi
    co ) ABCADCAEFZGPHFZIOJQGKFCPQAPLQLMN $.

  $( A subcomplex module is an additive group.  (Contributed by Mario Carneiro,
     16-Oct-2015.) $)
  clmgrp $p |- ( W e. CMod -> W e. Grp ) $=
    ( cclm wcel clmod cgrp clmlmod lmodgrp syl ) ABCADCAECAFAGH $.

  $( A subcomplex module is an abelian group.  (Contributed by Mario Carneiro,
     16-Oct-2015.) $)
  clmabl $p |- ( W e. CMod -> W e. Abel ) $=
    ( cclm wcel clmod cabl clmlmod lmodabl syl ) ABCADCAECAFAGH $.

  ${
    clm0.f $e |- F = ( Scalar ` W ) $.
    $( The scalar ring of a subcomplex module is a ring.  (Contributed by Mario
       Carneiro, 16-Oct-2015.) $)
    clmring $p |- ( W e. CMod -> F e. Ring ) $=
      ( cclm wcel clmod crg clmlmod lmodring syl ) BDEBFEAGEBHABCIJ $.

    $( The scalar ring of a subcomplex module is a group.  (Contributed by
       Mario Carneiro, 16-Oct-2015.) $)
    clmfgrp $p |- ( W e. CMod -> F e. Grp ) $=
      ( cclm wcel clmod cgrp clmlmod lmodfgrp syl ) BDEBFEAGEBHABCIJ $.

    $( The zero of the scalar ring of a subcomplex module.  (Contributed by
       Mario Carneiro, 16-Oct-2015.) $)
    clm0 $p |- ( W e. CMod -> 0 = ( 0g ` F ) ) $=
      ( cclm wcel cc0 ccnfld cbs cfv cress c0g csubrg wceq eqid clmsubrg cnfld0
      co subrg0 syl clmsca fveq2d eqtr4d ) BDEZFGAHIZJQZKIZAKIUCUDGLIEFUFMAUDBC
      UDNZOUDGUEFUENPRSUCAUEKAUDBCUGTUAUB $.

    $( The identity of the scalar ring of a subcomplex module.  (Contributed by
       Mario Carneiro, 16-Oct-2015.) $)
    clm1 $p |- ( W e. CMod -> 1 = ( 1r ` F ) ) $=
      ( cclm wcel c1 ccnfld cbs cfv cress co cur csubrg wceq eqid cnfld1 subrg1
      clmsubrg syl clmsca fveq2d eqtr4d ) BDEZFGAHIZJKZLIZALIUCUDGMIEFUFNAUDBCU
      DOZRUDGUEFUEOPQSUCAUELAUDBCUGTUAUB $.

    $( The addition of the scalar ring of a subcomplex module.  (Contributed by
       Mario Carneiro, 16-Oct-2015.) $)
    clmadd $p |- ( W e. CMod -> + = ( +g ` F ) ) $=
      ( cclm wcel caddc ccnfld cbs cfv cress cplusg cvv wceq fvex eqid cnfldadd
      co ressplusg ax-mp clmsca fveq2d eqtr4id ) BDEZFGAHIZJQZKIZAKIUDLEFUFMAHN
      UDFGUELUEOPRSUCAUEKAUDBCUDOTUAUB $.

    $( The multiplication of the scalar ring of a subcomplex module.
       (Contributed by Mario Carneiro, 16-Oct-2015.) $)
    clmmul $p |- ( W e. CMod -> x. = ( .r ` F ) ) $=
      ( cclm wcel cmul ccnfld cbs cfv cress co cmulr cvv wceq cnfldmul ressmulr
      fvex eqid ax-mp clmsca fveq2d eqtr4id ) BDEZFGAHIZJKZLIZALIUDMEFUFNAHQUDG
      UEFMUEROPSUCAUELAUDBCUDRTUAUB $.

    $( The conjugation of the scalar ring of a subcomplex module.  (Contributed
       by Mario Carneiro, 16-Oct-2015.) $)
    clmcj $p |- ( W e. CMod -> * = ( *r ` F ) ) $=
      ( cclm wcel ccj ccnfld cbs cfv cress co cstv cvv wceq fvex eqid ressstarv
      cnfldcj ax-mp clmsca fveq2d eqtr4id ) BDEZFGAHIZJKZLIZALIUDMEFUFNAHOUDGUE
      FMUEPRQSUCAUELAUDBCUDPTUAUB $.

    $( Reverse direction of ~ isclm .  (Contributed by Mario Carneiro,
       30-Oct-2015.) $)
    isclmi $p |- ( ( W e. LMod /\ F = ( CCfld |`s K ) /\
                     K e. ( SubRing ` CCfld ) ) -> W e. CMod ) $=
      ( clmod wcel ccnfld cress co wceq csubrg cfv w3a cbs simp1 simp2 subrgbas
      cclm eqid 3ad2ant3 fveq2d eqtr4d oveq2d eqtrd simp3 eqeltrrd syl3anbrc
      isclm ) CEFZAGBHIZJZBGKLZFZMZUIAGANLZHIZJUOULFCRFUIUKUMOUNAUJUPUIUKUMPZUN
      BUOGHUNBUJNLZUOUMUIBURJUKBGUJUJSQTUNAUJNUQUAUBZUCUDUNBUOULUSUIUKUMUEUFAUO
      CDUOSUHUG $.

    clmsub.k $e |- K = ( Base ` F ) $.
    $( The scalar ring of a subcomplex module contains the integers.
       (Contributed by Mario Carneiro, 16-Oct-2015.) $)
    clmzss $p |- ( W e. CMod -> ZZ C_ K ) $=
      ( cclm wcel ccnfld csubrg cfv cz wss clmsubrg zsssubrg syl ) CFGBHIJGKBLA
      BCDEMBNO $.

    $( The scalar ring of a subcomplex module is a subset of the complex
       numbers.  (Contributed by Mario Carneiro, 16-Oct-2015.) $)
    clmsscn $p |- ( W e. CMod -> K C_ CC ) $=
      ( cclm wcel ccnfld csubrg cfv cc wss clmsubrg cnfldbas subrgss syl ) CFGB
      HIJGBKLABCDEMBKHNOP $.

    $( Subtraction in the scalar ring of a subcomplex module.  (Contributed by
       Mario Carneiro, 16-Oct-2015.) $)
    clmsub $p |- ( ( W e. CMod /\ A e. K /\ B e. K ) ->
      ( A - B ) = ( A ( -g ` F ) B ) ) $=
      ( cclm wcel w3a cmin co ccnfld cress csg cfv csubg wceq csubrg eqid oveqd
      clmsubrg subrgsubg cnfldsub subgsub syl3an1 clmsca fveq2d 3ad2ant1 eqtr4d
      syl ) EHIZADIZBDIZJZABKLZABMDNLZOPZLZABCOPZLULDMQPIZUMUNUPUSRULDMSPIVACDE
      FGUBDMUCUKDMUQKURABUDUQTURTUEUFUOUTURABULUMUTURRUNULCUQOCDEFGUGUHUIUAUJ
      $.

    $( Negation in the scalar ring of a subcomplex module.  (Contributed by
       Mario Carneiro, 16-Oct-2015.) $)
    clmneg $p |- ( ( W e. CMod /\ A e. K ) -> -u A = ( ( invg ` F ) ` A ) ) $=
      ( cclm wcel wa cminusg cfv ccnfld cress co cneg wceq clmsca syl eqid cc
      fveq2d adantr fveq1d csubg csubrg clmsubrg subrgsubg subginv sylan sselda
      clmsscn cnfldneg 3eqtr2rd ) DGHZACHZIZABJKZKALCMNZJKZKZALJKZKZAOZUPAUQUSU
      NUQUSPUOUNBURJBCDEFQUAUBUCUNCLUDKHZUOVBUTPUNCLUEKHVDBCDEFUFCLUGRCLURVAUSA
      URSVASUSSUHUIUPATHVBVCPUNCTABCDEFUKUJAULRUM $.

    $( Minus one is in the scalar ring of a subcomplex module.  (Contributed by
       AV, 28-Sep-2021.) $)
    clmneg1 $p |- ( W e. CMod -> -u 1 e. K ) $=
      ( cclm wcel cz wss c1 cneg clmzss neg1z ssel mpisyl ) CFGHBIJKZHGPBGABCDE
      LMHBPNO $.

    $( Norm in the scalar ring of a subcomplex module.  (Contributed by Mario
       Carneiro, 16-Oct-2015.) $)
    clmabs $p |- ( ( W e. CMod /\ A e. K ) ->
      ( abs ` A ) = ( ( norm ` F ) ` A ) ) $=
      ( cclm wcel wa cnm cfv ccnfld cress cabs wceq clmsca fveq2d adantr eqid
      co fveq1d csubg csubrg clmsubrg subrgsubg cnfldnm subgnm2 sylan eqtr2d
      syl ) DGHZACHZIZABJKZKALCMTZJKZKZANKZUMAUNUPUKUNUPOULUKBUOJBCDEFPQRUAUKCL
      UBKHZULUQUROUKCLUCKHUSBCDEFUDCLUEUJCLUOUPNAUOSUFUPSUGUHUI $.

    $( Closure of ring addition for a subcomplex module.  (Contributed by Mario
       Carneiro, 16-Oct-2015.) $)
    clmacl $p |- ( ( W e. CMod /\ X e. K /\ Y e. K ) -> ( X + Y ) e. K ) $=
      ( cclm wcel ccnfld csubrg cfv caddc co clmsubrg cnfldadd subrgacl syl3an1
      ) CHIBJKLIDBIEBIDEMNBIABCFGOBMJDEPQR $.

    $( Closure of ring multiplication for a subcomplex module.  (Contributed by
       Mario Carneiro, 16-Oct-2015.) $)
    clmmcl $p |- ( ( W e. CMod /\ X e. K /\ Y e. K ) -> ( X x. Y ) e. K ) $=
      ( cclm wcel ccnfld csubrg cfv cmul co clmsubrg cnfldmul subrgmcl syl3an1
      ) CHIBJKLIDBIEBIDEMNBIABCFGOBJMDEPQR $.

    $( Closure of ring subtraction for a subcomplex module.  (Contributed by
       Mario Carneiro, 16-Oct-2015.) $)
    clmsubcl $p |- ( ( W e. CMod /\ X e. K /\ Y e. K ) -> ( X - Y ) e. K ) $=
      ( cclm wcel ccnfld csubg cfv cmin csubrg clmsubrg subrgsubg syl subgsubcl
      co cnfldsub syl3an1 ) CHIZBJKLIZDBIEBIDEMSBIUBBJNLIUCABCFGOBJPQBJMDETRUA
      $.
  $}

  $( The domain of a linear operator is a subcomplex module iff the range is.
     (Contributed by Mario Carneiro, 21-Oct-2015.) $)
  lmhmclm $p |- ( F e. ( S LMHom T ) -> ( S e. CMod <-> T e. CMod ) ) $=
    ( clmhm wcel clmod csca cfv ccnfld cbs cress wceq csubrg w3a cclm lmhmlmod1
    co lmhmlmod2 eqid isclm 2thd lmhmsca eqcomd fveq2d oveq2d eqeq12d 3anbi123d
    eleq1d 3bitr4g ) CABDQEZAFEZAGHZIULJHZKQZLZUMIMHZEZNBFEZBGHZIUSJHZKQZLZUTUP
    EZNAOEBOEUJUKURUOVBUQVCUJUKURABCPABCRUAUJULUSUNVAUJUSULABCULUSULSZUSSZUBUCZ
    UJUMUTIKUJULUSJVFUDZUEUFUJUMUTUPVGUHUGULUMAVDUMSTUSUTBVEUTSTUI $.

  ${
    clmvscl.v $e |- V = ( Base ` W ) $.
    clmvscl.f $e |- F = ( Scalar ` W ) $.
    clmvscl.s $e |- .x. = ( .s ` W ) $.
    clmvscl.k $e |- K = ( Base ` F ) $.
    $( Closure of scalar product for a subcomplex module.  Analogue of
       ~ lmodvscl .  (Contributed by NM, 3-Nov-2006.)  (Revised by AV,
       28-Sep-2021.) $)
    clmvscl $p |- ( ( W e. CMod /\ Q e. K /\ X e. V )
                    -> ( Q .x. X ) e. V ) $=
      ( cclm wcel clmod co clmlmod lmodvscl syl3an1 ) FLMFNMADMGEMAGBOEMFPABCDE
      FGHIJKQR $.

    $( Associative law for scalar product.  Analogue of ~ lmodvsass .
       (Contributed by Mario Carneiro, 16-Oct-2015.) $)
    clmvsass $p |- ( ( W e. CMod /\ ( Q e. K /\ R e. K /\ X e. V ) ) ->
                      ( ( Q x. R ) .x. X ) = ( Q .x. ( R .x. X ) ) ) $=
      ( cclm wcel w3a wa cmul co cmulr wceq cfv clmmul adantr oveqd oveq1d eqid
      clmod clmlmod lmodvsass sylan eqtrd ) GMNZAENBENHFNOZPZABQRZHCRABDSUAZRZH
      CRZABHCRCRZUNUOUQHCUNQUPABULQUPTUMDGJUBUCUDUEULGUGNUMURUSTGUHABCUPDEFGHIJ
      KLUPUFUIUJUK $.

    $( Commutative law for the scalar product.  (Contributed by NM,
       14-Feb-2008.)  (Revised by AV, 7-Oct-2021.) $)
    clmvscom $p |- ( ( W e. CMod /\ ( Q e. K /\ R e. K /\ X e. V ) )
                     -> ( Q .x. ( R .x. X ) ) = ( R .x. ( Q .x. X ) ) ) $=
      ( wcel w3a wa cmul co cc wceq ssel cclm wss anim12d clmsscn syl11 3adant3
      wi impcom mulcom syl oveq1d clmvsass 3ancoma sylan2b 3eqtr3d ) GUAMZAEMZB
      EMZHFMZNZOZABPQZHCQBAPQZHCQZABHCQCQBAHCQCQZVAVBVCHCVAARMZBRMZOZVBVCSUTUPV
      HUQURUPVHUGUSERUBZUQUROVHUPVIUQVFURVGERATERBTUCDEGJLUDUEUFUHABUIUJUKABCDE
      FGHIJKLULUTUPURUQUSNVDVESUQURUSUMBACDEFGHIJKLULUNUO $.

    clmvsdir.a $e |- .+ = ( +g ` W ) $.
    $( Distributive law for scalar product (right-distributivity).
